    open(f'{R}/assets/badges/{fid}.svg','w').write(f'<svg xmlns="http://www.w3.org/2000/svg" width="{wk+wv}" height="26" role="img" aria-label="{k}: {v}"><defs><linearGradient id="g" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".25"/><stop offset="1" stop-opacity=".12"/></linearGradient></defs><rect width="{wk}" height="26" rx="6" fill="#1c1b3a"/><rect x="{wk-6}" width="{wv+6}" height="26" rx="6" fill="{col}"/><rect width="{wk+wv}" height="26" rx="6" fill="url(#g)"/><g fill="#fff" font-family="system-ui,Segoe UI,sans-serif" font-size="12" font-weight="600"><text x="9" y="17">{k}</text><text x="{wk+9}" y="17">{v}</text></g></svg>')
